grid = [[7]*19 for _ in range(10)]
pts=[(0,14),(1,0),(1,2),(1,4),(1,6),(1,8),(1,10),(1,13),(1,15),(1,17),(2,9),(2,16),(3,0),(3,8),(3,16),(4,4),(4,8),(5,15),(6,4),(6,6),(6,11),(6,13),(7,7),(7,16),(8,2),(8,6),(8,13),(8,15),(9,7)]
for r,c in pts: grid[r][c]=2
for r in range(10):
    cols=[c for rr,c in pts if rr==r]
    if len(cols)>=2:
        for c in range(min(cols),max(cols)+1):
            if grid[r][c]==7: grid[r][c]=3
for c in range(19):
    rows=[r for r,cc in pts if cc==c]
    if len(rows)>=2:
        for r in range(min(rows),max(rows)+1):
            if grid[r][c]==7: grid[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in grid))
